window.CODE_INDEX = {"classes":{"AppLanguageDropdown":{"appearsIn":[["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"export function AppLanguageDropdown() {\n  const t = useTheme()\n  const {_} = useLingui()\n\n  const queryClient = useQueryClient()\n  const langPrefs = useLanguagePrefs()\n  const setLangPrefs = useLanguagePrefsApi()\n  const sanitizedLang = sanitizeAppLanguageSetting(langPrefs.appLanguage)\n\n  const onChangeAppLanguage = useCallback(\n    (value: string) => {\n      if (!value) return\n      if (sanitizedLang !== value) {\n        setLangPrefs.setAppLanguage(sanitizeAppLanguageSetting(value))\n      }\n\n      // reset feeds to refetch content\n      resetPostsFeedQueries(queryClient)\n    },\n    [sanitizedLang, setLangPrefs, queryClient],\n  )\n\n  return (\n    <Select.Root\n      value={sanitizeAppLanguageSetting(langPrefs.appLanguage)}\n      onValueChange={onChangeAppLanguage}>\n      <Select.Trigger label={_(msg`Change app language`)}>\n        {({props}) => (\n          <Button\n            {...props}\n            label={props.accessibilityLabel}\n            size={platform({\n              web: 'tiny',\n              native: 'small',\n            })}\n            variant=\"ghost\"\n            color=\"secondary\"\n            shape=\"rectangular\"\n            style={[\n              a.pr_xs,\n              a.pl_sm,\n              platform({\n                web: [{alignSelf: 'flex-start'}, a.gap_sm],\n                native: [a.gap_xs],\n              }),\n            ]}>\n            <ButtonIcon icon={EarthIcon} size=\"md\" />\n            <Select.ValueText\n              placeholder={_(msg`Select an app language`)}\n              style={[t.atoms.text_contrast_medium]}\n            />\n            <Select.Icon style={[t.atoms.text_contrast_medium]} />\n          </Button>\n        )}\n      </Select.Trigger>\n      <Select.Content\n        label={_(msg`Select language`)}\n        renderItem={({label, value}) => (\n          <Select.Item value={value} label={label} style={web([a.pointer])}>\n            <Select.ItemIndicator />\n            <Select.ItemText>{label}</Select.ItemText>\n          </Select.Item>\n        )}\n        items={APP_LANGUAGES.map(l => ({\n          label: l.name,\n          value: l.code2,\n        }))}\n      />\n    </Select.Root>\n  )\n}","file":"src/components/AppLanguageDropdown.tsx","kind":"component","line":15,"members":{"langPrefs":[20,20],"onChangeAppLanguage":[24,35],"queryClient":[19,19],"setLangPrefs":[21,21],"t":[16,16]},"shot":"shots/code/AppLanguageDropdown.jpg","supers":[]},"BackNextButtons":{"appearsIn":[["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"export function BackNextButtons({\n  hideNext,\n  showRetry,\n  isLoading,\n  isNextDisabled,\n  onBackPress,\n  onNextPress,\n  onRetryPress,\n  overrideNextText,\n}: BackNextButtonsProps) {\n  const {_} = useLingui()\n\n  return (\n    <View style={[a.flex_row, a.justify_between, a.pb_lg, a.pt_3xl]}>\n      <Button\n        label={_(msg`Go back to previous step`)}\n        variant=\"solid\"\n        color=\"secondary\"\n        size=\"large\"\n        onPress={onBackPress}>\n        <ButtonText>\n          <Trans>Back</Trans>\n        </ButtonText>\n      </Button>\n      {!hideNext &&\n        (showRetry ? (\n          <Button\n            label={_(msg`Press to retry`)}\n            variant=\"solid\"\n            color=\"primary\"\n            size=\"large\"\n            onPress={onRetryPress}>\n            <ButtonText>\n              <Trans>Retry</Trans>\n            </ButtonText>\n            {isLoading && <ButtonIcon icon={Loader} />}\n          </Button>\n        ) : (\n          <Button\n            testID=\"nextBtn\"\n            label={_(msg`Continue to next step`)}\n            variant=\"solid\"\n            color=\"primary\"\n            size=\"large\"\n            disabled={isLoading || isNextDisabled}\n            onPress={onNextPress}>\n            <ButtonText>\n              {overrideNextText ? overrideNextText : <Trans>Next</Trans>}\n            </ButtonText>\n            {isLoading && <ButtonIcon icon={Loader} />}\n          </Button>\n        ))}\n    </View>\n  )\n}","file":"src/screens/Signup/BackNextButtons.tsx","kind":"component","line":21,"members":{"hideNext":[21,30],"isLoading":[21,30],"isNextDisabled":[21,30],"onBackPress":[21,30],"onNextPress":[21,30],"onRetryPress":[21,30],"overrideNextText":[21,30],"showRetry":[21,30]},"shot":"shots/code/BackNextButtons.jpg","supers":[]},"DateField":{"alsoIn":["src/components/forms/DateField/index.android.tsx","src/components/forms/DateField/index.web.tsx"],"appearsIn":[["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"/**\n * Date-only input. Accepts a string in the format YYYY-MM-DD, or a Date object.\n * Date objects are converted to strings in the format YYYY-MM-DD.\n * Returns a string in the format YYYY-MM-DD.\n *\n * To generate a string in the format YYYY-MM-DD from a Date object, use the\n * `utils.toSimpleDateString(Date)` export of this file.\n */\nexport function DateField({\n  value,\n  inputRef,\n  onChangeDate,\n  onConfirm,\n  placeholder,\n  testID,\n  label,\n  isInvalid,\n  accessibilityHint,\n  maximumDate,\n  minimumDate,\n}: DateFieldProps) {\n  const {_, i18n} = useLingui()\n  const t = useTheme()\n  const control = Dialog.useDialogControl()\n\n  /*\n   * The picker requires a valid date, so when value is empty we fall back to\n   * maximumDate (if set) or today. Draft state lets the picker scroll even when\n   * the parent does not echo value back (e.g. a clearable field).\n   */\n  const fallbackDate = maximumDate\n    ? toSimpleDateString(maximumDate)\n    : toSimpleDateString(new Date())\n  const [draft, setDraft] = useState(() =>\n    value === '' ? fallbackDate : toSimpleDateString(value),\n  )\n\n  const onChangeInternal = useCallback(\n    (date: Date | undefined) => {\n      if (date) {\n        const formatted = toSimpleDateString(date)\n        setDraft(formatted)\n        onChangeDate(formatted)\n      }\n    },\n    [onChangeDate],\n  )\n\n  useImperativeHandle(\n    inputRef,\n    () => ({\n      focus: () => {\n        Keyboard.dismiss()\n        setDraft(value === '' ? fallbackDate : toSimpleDateString(value))\n        control.open()\n      },\n      blur: () => {\n        control.close()\n      },\n    }),\n    [control, value, fallbackDate],\n  )\n\n  return (\n    <>\n      <DateFieldButton\n        label={label}\n        value={value}\n        placeholder={placeholder}\n        onPress={() => {\n          Keyboard.dismiss()\n          setDraft(value === '' ? fallbackDate : toSimpleDateString(value))\n          control.open()\n        }}\n        isInvalid={isInvalid}\n        accessibilityHint={accessibilityHint}\n      />\n      <Dialog.Outer\n        control={control}\n        testID={testID}\n        nativeOptions={{preventExpansion: true}}>\n        <Dialog.Handle />\n        <Dialog.ScrollableInner label={label}>\n          <View style={a.gap_lg}>\n            <View style={[a.relative, a.w_full, a.align_center]}>\n              <DateTimePicker\n                style={a.w_full}\n                value={new Date(draft)}\n                onValueChange={(_event, date) => onChangeInternal(date)}\n                mode=\"date\"\n                display=\"spinner\"\n                timeZoneName=\"UTC\"\n                themeVariant={t.scheme}\n                locale={toAppleLocale(i18n.locale)}\n                testID={`${testID}-datepicker`}\n                maximumDate={\n                  maximumDate\n                    ? new Date(toSimpleDateString(maximumDate))\n                    : undefined\n                }\n                minimumDate={\n                  minimumDate\n                    ? new Date(toSimpleDateString(minimumDate))\n                    : undefined\n                }\n              />\n            </View>\n            <Button\n              label={_(msg`Done`)}\n              onPress={() => {\n                /*\n                 * Commit the currently shown date even if the user never\n                 * scrolled (onDateChange only fires on scroll). This keeps\n                 * onChangeDate firing alongside onConfirm, matching Android and\n                 * web, so an empty field confirmed without scrolling does not\n                 * report a date via onConfirm while onChangeDate stays silent.\n                 */\n                onChangeDate(draft)\n                onConfirm?.(draft)\n                control.close()\n              }}\n              size=\"large\"\n              color=\"primary\"\n              variant=\"solid\">\n              <ButtonText>\n                <Trans>Done</Trans>\n              </ButtonText>\n            </Button>\n          </View>\n        </Dialog.ScrollableInner>\n      </Dialog.Outer>\n    </>\n  )\n}","file":"src/components/forms/DateField/index.tsx","kind":"component","line":28,"members":{"accessibilityHint":[36,48],"control":[51,51],"draft":[61,63],"inputRef":[36,48],"isInvalid":[36,48],"label":[36,48],"maximumDate":[36,48],"minimumDate":[36,48],"onChangeDate":[36,48],"onChangeInternal":[65,74],"onConfirm":[36,48],"placeholder":[36,48],"t":[50,50],"testID":[36,48],"value":[36,48]},"shot":"shots/code/DateField.jpg","supers":[]},"HostingProvider":{"appearsIn":[["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"export function HostingProvider({\n  serviceUrl,\n  onSelectServiceUrl,\n  onOpenDialog,\n  minimal,\n}: {\n  serviceUrl: string\n  onSelectServiceUrl: (provider: string) => void\n  onOpenDialog?: () => void\n  minimal?: boolean\n}) {\n  const serverInputControl = useDialogControl()\n  const t = useTheme()\n  const {_} = useLingui()\n\n  const onPressSelectService = useCallback(() => {\n    Keyboard.dismiss()\n    serverInputControl.open()\n    onOpenDialog?.()\n  }, [onOpenDialog, serverInputControl])\n\n  return (\n    <>\n      <ServerInputDialog\n        control={serverInputControl}\n        onSelect={onSelectServiceUrl}\n      />\n      {minimal ? (\n        <View style={[a.flex_row, a.align_center, a.flex_wrap, a.gap_xs]}>\n          <Text style={[a.text_sm, t.atoms.text_contrast_medium]}>\n            <Trans>You are creating an account on</Trans>\n          </Text>\n          <Button\n            label={toNiceDomain(serviceUrl)}\n            accessibilityHint={_(msg`Changes hosting provider`)}\n            onPress={onPressSelectService}\n            variant=\"ghost\"\n            color=\"secondary\"\n            size=\"tiny\"\n            style={[\n              a.px_xs,\n              {marginHorizontal: tokens.space.xs * -1},\n              {paddingVertical: 0},\n            ]}>\n            <ButtonText style={[a.text_sm]}>\n              {toNiceDomain(serviceUrl)}\n            </ButtonText>\n            <ButtonIcon icon={PencilIcon} />\n          </Button>\n        </View>\n      ) : (\n        <Button\n          testID=\"selectServiceButton\"\n          label={toNiceDomain(serviceUrl)}\n          accessibilityHint={_(msg`Changes hosting provider`)}\n          variant=\"solid\"\n          color=\"secondary\"\n          style={[\n            a.w_full,\n            a.flex_row,\n            a.align_center,\n            a.rounded_sm,\n            a.py_sm,\n            a.pl_md,\n            a.pr_sm,\n            a.gap_xs,\n          ]}\n          onPress={onPressSelectService}>\n          {({hovered, pressed}) => {\n            const interacted = hovered || pressed\n            return (\n              <>\n                <View style={a.pr_xs}>\n                  <GlobeIcon\n                    size=\"md\"\n                    fill={\n                      interacted\n                        ? t.palette.contrast_800\n                        : t.palette.contrast_500\n                    }\n                  />\n                </View>\n                <Text style={[a.text_md]}>{toNiceDomain(serviceUrl)}</Text>\n                <View\n                  style={[\n                    a.rounded_sm,\n                    interacted\n                      ? t.atoms.bg_contrast_300\n                      : t.atoms.bg_contrast_100,\n                    {marginLeft: 'auto', padding: 6},\n                  ]}>\n                  <PencilIcon\n                    size=\"sm\"\n                    style={{\n                      color: interacted\n                        ? t.palette.contrast_800\n                        : t.palette.contrast_500,\n                    }}\n                  />\n                </View>\n              </>\n            )\n          }}\n        </Button>\n      )}\n    </>\n  )\n}","file":"src/components/forms/HostingProvider.tsx","kind":"component","line":16,"members":{"minimal":[16,26],"onOpenDialog":[16,26],"onPressSelectService":[31,35],"onSelectServiceUrl":[16,26],"serverInputControl":[27,27],"serviceUrl":[16,26],"t":[28,28]},"shot":"shots/code/HostingProvider.jpg","supers":[]},"PasswordField":{"appearsIn":[["sign-in","h-widgets","Screen \u00b7 component composition"],["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"/**\n * Password input with a lock icon and a reveal/hide toggle. Callers keep\n * ownership of autocomplete, password rules, and submit behavior.\n */\nexport function PasswordField({\n  isInvalid = false,\n  value,\n  autoCapitalize = 'none',\n  autoCorrect = false,\n  hitSlop = {...HITSLOP_20, right: 0},\n  ...rest\n}: Omit<TextField.InputProps, 'secureTextEntry' | 'children'>) {\n  const [revealPassword, setRevealPassword] = useState(false)\n\n  return (\n    <TextField.Root isInvalid={isInvalid}>\n      <TextField.Icon icon={LockIcon} />\n      <TextField.Input\n        {...rest}\n        value={value}\n        autoCapitalize={autoCapitalize}\n        autoCorrect={autoCorrect}\n        hitSlop={hitSlop}\n        secureTextEntry={!revealPassword}\n      />\n      <RevealPasswordButton\n        active={revealPassword}\n        hasPassword={!!value}\n        onPress={() => setRevealPassword(r => !r)}\n      />\n    </TextField.Root>\n  )\n}","file":"src/components/forms/PasswordField.tsx","kind":"component","line":13,"members":{"autoCapitalize":[17,24],"autoCorrect":[17,24],"hitSlop":[17,24],"isInvalid":[17,24],"rest":[17,24],"revealPassword":[25,25],"value":[17,24]},"shot":"shots/code/PasswordField.jpg","supers":[]},"SessionApiContext":{"appearsIn":[["launch","h-classes","Logic \u00b7 class diagram"],["launch","h-sequence","Cold start \u00b7 sequence"],["sign-in","h-classes","Logic \u00b7 class diagram"],["sign-in","h-sequence","Sign in \u00b7 sequence"],["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-sequence","Create an account \u00b7 sequence"]],"code":"export type SessionApiContext = {\n  createAccount: (\n    props: {\n      service: string\n      email: string\n      password: string\n      handle: string\n      birthDate: Date\n      inviteCode?: string\n      verificationPhone?: string\n      verificationCode?: string\n    },\n    metrics: Metrics['account:create:success'],\n  ) => Promise<void>\n  login: (\n    props: {\n      service: string\n      identifier: string\n      password: string\n      authFactorToken?: string | undefined\n    },\n    logContext: Metrics['account:loggedIn']['logContext'],\n  ) => Promise<void>\n  logoutCurrentAccount: (\n    logContext: Metrics['account:loggedOut']['logContext'],\n  ) => void\n  logoutEveryAccount: (\n    logContext: Metrics['account:loggedOut']['logContext'],\n  ) => void\n  resumeSession: (\n    account: SessionAccount,\n    isSwitchingAccounts?: boolean,\n  ) => Promise<void>\n  removeAccount: (account: SessionAccount) => void\n  /**\n   * Calls `getSession` and patches the email fields of the current account.\n   * Unlike `resumeSession`, this does not rotate tokens or rebuild the session,\n   * so it produces no session-change side effects.\n   */\n  partialRefreshSession: () => Promise<void>\n  /**\n   * Rotates the session's tokens and resolves with the resulting account\n   * snapshot, or `undefined` when logged out.\n   *\n   * Rejects when nothing was rotated, so a resolved promise means \"tokens\n   * rotated\". Every caller relies on that: the verification dialogs close on\n   * resolution, and `SignupQueued` re-checks the token scope.\n   *\n   * The snapshot is returned rather than read off `currentAccount`, because the\n   * session's `onUpdated` hook -> `store.dispatch` path is a render cycle away\n   * and `SignupQueued` branches synchronously on the fresh `accessJwt`.\n   */\n  refreshSession: () => Promise<SessionAccount | undefined>\n}","file":"src/state/session/types.ts","kind":"type","line":15,"members":{"createAccount":[16,28],"login":[29,37],"logoutCurrentAccount":[38,40],"logoutEveryAccount":[41,43],"partialRefreshSession":[54,54],"refreshSession":[67,67],"removeAccount":[48,48],"resumeSession":[44,47]},"shot":"shots/code/SessionApiContext.jpg","supers":[]},"Signup":{"appearsIn":[["launch","h-widgets","Screen \u00b7 component composition"],["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"export function Signup({onPressBack}: {onPressBack: () => void}) {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const t = useTheme()\n  const [state, dispatch] = useReducer(reducer, {\n    ...initialState,\n    analytics: ax,\n  })\n  const {gtMobile} = useBreakpoints()\n  const submit = useSubmitSignup()\n\n  useEffect(() => {\n    dispatch({\n      type: 'setAnalytics',\n      value: ax,\n    })\n  }, [ax])\n\n  const activeStarterPack = useActiveStarterPack()\n  const {\n    data: starterPack,\n    isFetching: isFetchingStarterPack,\n    isError: isErrorStarterPack,\n  } = useStarterPackQuery({\n    uri: activeStarterPack?.uri,\n  })\n\n  // eslint-disable-next-line react/hook-use-state\n  const [isFetchedAtMount] = useState(starterPack != null)\n  const showStarterPackCard =\n    activeStarterPack?.uri && !isFetchingStarterPack && starterPack\n\n  const {\n    data: serviceInfo,\n    isFetching,\n    isError,\n    refetch,\n  } = useServiceQuery(state.serviceUrl)\n\n  useEffect(() => {\n    if (isFetching) {\n      dispatch({type: 'setIsLoading', value: true})\n    } else if (!isFetching) {\n      dispatch({type: 'setIsLoading', value: false})\n    }\n  }, [isFetching])\n\n  useEffect(() => {\n    if (isError) {\n      dispatch({type: 'setServiceDescription', value: undefined})\n      dispatch({\n        type: 'setError',\n        value: l`Unable to contact your service. Please check your Internet connection.`,\n      })\n    } else if (serviceInfo) {\n      dispatch({type: 'setServiceDescription', value: serviceInfo})\n      dispatch({type: 'setError', value: ''})\n    }\n  }, [l, serviceInfo, isError])\n\n  useEffect(() => {\n    if (state.pendingSubmit) {\n      if (!state.pendingSubmit.mutableProcessed) {\n        // OK to mutate assuming it's never read in render.\n        // eslint-disable-next-line react-hooks/immutability, react-compiler/react-compiler\n        state.pendingSubmit.mutableProcessed = true\n        void submit(state, dispatch)\n      }\n    }\n  }, [state, dispatch, submit])\n\n  // Track app backgrounding during signup\n  useEffect(() => {\n    const subscription = AppState.addEventListener(\n      'change',\n      (nextAppState: AppStateStatus) => {\n        if (nextAppState === 'background') {\n          dispatch({type: 'incrementBackgroundCount'})\n        }\n      },\n    )\n\n    return () => subscription.remove()\n  }, [])\n\n  // On Android, warmup the Play Integrity API on the signup screen so it is ready by the time we get to the gate screen.\n  useEffect(() => {\n    if (!IS_ANDROID) {\n      return\n    }\n    ReactNativeDeviceAttest.warmupIntegrity(GCP_PROJECT_ID).catch(err =>\n      logger.error(err),\n    )\n  }, [])\n\n  return (\n    <Animated.View exiting={native(FadeIn.duration(90))} style={a.flex_1}>\n      <SignupContext.Provider value={{state, dispatch}}>\n        <SignupKeyboardAvoidingView\n          enabled={state.activeStep !== SignupStep.CAPTCHA}>\n          <LoggedOutLayout\n            leadin=\"\"\n            title={l`Create account`}\n            description={l`We\u2019re so excited to have you join us!`}\n            scrollable>\n            <View testID=\"createAccount\" style={a.flex_1}>\n              {showStarterPackCard &&\n              bsky.isType(app.bsky.graph.starterpack, starterPack.record) ? (\n                <Animated.View\n                  entering={!isFetchedAtMount ? FadeIn : undefined}>\n                  <LinearGradientBackground\n                    style={[a.mx_lg, a.p_lg, a.gap_sm, a.rounded_sm]}>\n                    <Text\n                      style={[a.font_semi_bold, a.text_xl, {color: 'white'}]}>\n                      {starterPack.record.name}\n                    </Text>\n                    <Text style={[{color: 'white'}]}>\n                      {starterPack.feeds?.length ? (\n                        <Trans>\n                          You'll follow the suggested users and feeds once you\n                          finish creating your account!\n                        </Trans>\n                      ) : (\n                        <Trans>\n                          You'll follow the suggested users once you finish\n                          creating your account!\n                        </Trans>\n                      )}\n                    </Text>\n                  </LinearGradientBackground>\n                </Animated.View>\n              ) : null}\n              <LayoutAnimationConfig skipEntering>\n                <ScreenTransition\n                  key={state.activeStep}\n                  direction={state.screenTransitionDirection}\n                  style={a.flex_1}>\n                  <View style={[a.flex_1, a.px_xl, a.pt_2xl]}>\n                    <View style={[a.gap_sm, a.pb_3xl]}>\n                      <Text\n                        style={[\n                          a.font_semi_bold,\n                          t.atoms.text_contrast_medium,\n                        ]}>\n                        <Trans>\n                          Step {state.activeStep + 1} of{' '}\n                          {state.serviceDescription &&\n                          !state.serviceDescription.phoneVerificationRequired\n                            ? '2'\n                            : '3'}\n                        </Trans>\n                      </Text>\n                      <Text style={[a.text_3xl, a.font_semi_bold]}>\n                        {state.activeStep === SignupStep.INFO ? (\n                          <Trans>Your account</Trans>\n                        ) : state.activeStep === SignupStep.HANDLE ? (\n                          <Trans>Choose your username</Trans>\n                        ) : (\n                          <Trans>Complete the challenge</Trans>\n                        )}\n                      </Text>\n                    </View>\n\n                    {state.activeStep === SignupStep.INFO ? (\n                      <StepInfo\n                        onPressBack={onPressBack}\n                        isLoadingStarterPack={\n                          isFetchingStarterPack && !isErrorStarterPack\n                        }\n                        isServerError={isError}\n                        refetchServer={() => void refetch()}\n                      />\n                    ) : state.activeStep === SignupStep.HANDLE ? (\n                      <StepHandle />\n                    ) : (\n                      <StepCaptcha />\n                    )}\n\n                    <Divider />\n\n                    <View\n                      style={[\n                        a.w_full,\n                        a.py_lg,\n                        a.flex_row,\n                        a.flex_wrap,\n                        a.gap_md,\n                        a.align_center,\n                      ]}>\n                      <AppLanguageDropdown />\n                      <View\n                        style={\n                          gtMobile\n                            ? [a.flex_1, a.flex, a.flex_row, a.justify_end]\n                            : [a.flex_shrink]\n                        }>\n                        <Text\n                          style={[\n                            t.atoms.text_contrast_medium,\n                            !gtMobile && a.text_md,\n                            {paddingInline: tokens.space.sm},\n                          ]}>\n                          <Trans>Having trouble?</Trans>{' '}\n                          <InlineLinkText\n                            label={l`Contact support`}\n                            to={FEEDBACK_FORM_URL({email: state.email})}\n                            style={[!gtMobile && a.text_md]}>\n                            <Trans>Contact support</Trans>\n                          </InlineLinkText>\n                        </Text>\n                      </View>\n                    </View>\n                  </View>\n                </ScreenTransition>\n              </LayoutAnimationConfig>\n            </View>\n          </LoggedOutLayout>\n        </SignupKeyboardAvoidingView>\n      </SignupContext.Provider>\n    </Animated.View>\n  )\n}","file":"src/screens/Signup/index.tsx","kind":"component","line":37,"members":{"activeStarterPack":[55,55],"ax":[38,38],"isFetchedAtMount":[65,65],"onPressBack":[37,37],"state":[41,44],"submit":[46,46],"t":[40,40]},"shot":"shots/code/Signup.jpg","supers":[]},"SignupContext":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"]],"code":"export const SignupContext = createContext<IContext>({} as IContext)","file":"src/screens/Signup/state.ts","kind":"context","line":244,"members":{},"shot":"shots/code/SignupContext.jpg","supers":[]},"SignupState":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"]],"code":"export type SignupState = {\n  analytics?: AnalyticsContextType\n\n  hasPrev: boolean\n  activeStep: SignupStep\n  screenTransitionDirection: 'Forward' | 'Backward'\n\n  serviceUrl: string\n  serviceDescription?: ServiceDescription\n  userDomain: string\n  dateOfBirth: Date | undefined\n  email: string\n  password: string\n  inviteCode: string\n  handle: string\n\n  error: string\n  errorField?: ErrorField\n  isLoading: boolean\n\n  pendingSubmit: null | SubmitTask\n\n  // Tracking\n  signupStartTime: number\n  fieldErrors: Record<ErrorField, number>\n  backgroundCount: number\n}","file":"src/screens/Signup/state.ts","kind":"type","line":32,"members":{"activeStep":[36,36],"analytics":[33,33],"backgroundCount":[57,57],"dateOfBirth":[42,42],"email":[43,43],"error":[48,48],"errorField":[49,49],"fieldErrors":[56,56],"handle":[46,46],"hasPrev":[35,35],"inviteCode":[45,45],"isLoading":[50,50],"password":[44,44],"pendingSubmit":[52,52],"screenTransitionDirection":[37,37],"serviceDescription":[40,40],"serviceUrl":[39,39],"signupStartTime":[55,55],"userDomain":[41,41]},"supers":[]},"SignupStep":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"]],"code":"export enum SignupStep {\n  INFO,\n  HANDLE,\n  CAPTCHA,\n}","file":"src/screens/Signup/state.ts","kind":"enum","line":18,"members":{"CAPTCHA":[21,21],"HANDLE":[20,20],"INFO":[19,19]},"supers":[]},"StepCaptcha":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-widgets","Screen \u00b7 component composition"]],"code":"export function StepCaptcha() {\n  if (IS_WEB) {\n    return <StepCaptchaInner />\n  } else {\n    return <StepCaptchaNative />\n  }\n}","file":"src/screens/Signup/StepCaptcha/index.tsx","kind":"component","line":59,"members":{},"supers":[]},"StepHandle":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-widgets","Screen \u00b7 component composition"],["sign-up","h-sequence","Create an account \u00b7 sequence"]],"code":"export function StepHandle() {\n  const {_} = useLingui()\n  const ax = useAnalytics()\n  const t = useTheme()\n  const {state, dispatch} = useSignupContext()\n  const [draftValue, setDraftValue] = useState(state.handle)\n  const isNextLoading = useThrottledValue(state.isLoading, 500)\n\n  /*\n   * Web anchors a floating Sift dropdown of suggestions to the input; native\n   * renders them inline and ignores this. `offset` leaves a small gap below the\n   * anchor, matching the inline `mt_xs` spacing.\n   */\n  const sift = useSift({offset: a.p_xs.padding, placement: 'bottom-start'})\n\n  const validCheck = validateServiceHandle(draftValue, state.userDomain)\n\n  const {\n    debouncedUsername: debouncedDraftValue,\n    enabled: queryEnabled,\n    query: {data: isHandleAvailable, isPending},\n  } = useHandleAvailabilityQuery({\n    username: draftValue,\n    serviceDid: state.serviceDescription?.did ?? 'UNKNOWN',\n    serviceDomain: state.userDomain,\n    birthDate: state.dateOfBirth?.toISOString() ?? '',\n    email: state.email,\n    enabled: validCheck.overall,\n  })\n\n  const onNextPress = async () => {\n    const handle = draftValue.trim()\n    dispatch({\n      type: 'setHandle',\n      value: handle,\n    })\n\n    if (!validCheck.overall) {\n      return\n    }\n\n    dispatch({type: 'setIsLoading', value: true})\n\n    const serviceDid = state.serviceDescription?.did ?? 'UNKNOWN'\n    try {\n      const {available: handleAvailable} = await checkHandleAvailability(\n        createFullHandle(handle, state.userDomain),\n        serviceDid,\n        {},\n      )\n\n      if (!handleAvailable) {\n        ax.metric('signup:handleTaken', {typeahead: false})\n        dispatch({\n          type: 'setError',\n          value: _(msg`That username is already taken`),\n          field: 'handle',\n        })\n        dispatch({type: 'setIsLoading', value: false})\n        return\n      } else {\n        ax.metric('signup:handleAvailable', {typeahead: false})\n      }\n    } catch (error) {\n      logger.error('Failed to check handle availability on next press', {\n        safeMessage: error,\n      })\n      // do nothing on error, let them pass\n    }\n    dispatch({type: 'setIsLoading', value: false})\n\n    ax.metric('signup:nextPressed', {\n      activeStep: state.activeStep,\n      phoneVerificationRequired:\n        state.serviceDescription?.phoneVerificationRequired,\n    })\n    // phoneVerificationRequired is actually whether a captcha is required\n    if (!state.serviceDescription?.phoneVerificationRequired) {\n      dispatch({\n        type: 'submit',\n        task: {verificationCode: undefined, mutableProcessed: false},\n      })\n      return\n    }\n    dispatch({type: 'next'})\n  }\n\n  const onBackPress = () => {\n    const handle = draftValue.trim()\n    dispatch({\n      type: 'setHandle',\n      value: handle,\n    })\n    dispatch({type: 'prev'})\n    ax.metric('signup:backPressed', {activeStep: state.activeStep})\n  }\n\n  const hasDebounceSettled = draftValue === debouncedDraftValue\n  const isHandleTaken =\n    !isPending &&\n    queryEnabled &&\n    isHandleAvailable &&\n    !isHandleAvailable.available\n  const isNotReady = isPending || !hasDebounceSettled\n  const isNextDisabled =\n    !validCheck.overall || !!state.error || isNotReady ? true : isHandleTaken\n\n  const textFieldInvalid =\n    isHandleTaken ||\n    !validCheck.frontLengthNotTooLong ||\n    !validCheck.handleChars ||\n    !validCheck.hyphenStartOrEnd ||\n    !validCheck.totalLength\n\n  /*\n   * Web-only Sift wiring. The anchor is the input section, whose bottom edge in\n   * the taken-and-valid state sits right below the availability error, so the\n   * floating dropdown lands beneath it. The input ref feeds Sift's keyboard\n   * handling and the combobox a11y props describe the typeahead relationship.\n   * Native ignores all of this and renders suggestions inline.\n   */\n  const {ref: inputAnchorRef, ...comboboxProps} = sift.targetProps\n\n  return (\n    <>\n      <View\n        collapsable={false}\n        ref={IS_WEB ? sift.refs.setAnchor : undefined}\n        onLayout={IS_WEB ? () => void sift.updatePosition() : undefined}\n        style={[a.gap_sm, a.pt_lg, a.z_10]}>\n        <View>\n          <TextField.Root isInvalid={textFieldInvalid}>\n            <TextField.Icon icon={AtIcon} />\n            <TextField.Input\n              {...(IS_WEB ? comboboxProps : {})}\n              inputRef={IS_WEB ? inputAnchorRef : undefined}\n              testID=\"handleInput\"\n              onChangeText={val => {\n                if (state.error) {\n                  dispatch({type: 'setError', value: ''})\n                }\n                setDraftValue(val.toLocaleLowerCase())\n              }}\n              label={state.userDomain}\n              value={draftValue}\n              keyboardType=\"ascii-capable\" // fix for iOS replacing -- with \u2014\n              autoCapitalize=\"none\"\n              autoCorrect={false}\n              autoFocus\n              autoComplete=\"off\"\n            />\n            {draftValue.length > 0 && (\n              <TextField.GhostText value={state.userDomain}>\n                {draftValue}\n              </TextField.GhostText>\n            )}\n            {isHandleAvailable?.available && (\n              /*\n               * Nano glyph icons are hidden from the accessibility tree, so\n               * the testID has to live on a wrapper for e2e flows to find it.\n               */\n              <View\n                testID=\"handleAvailableCheck\"\n                accessible\n                accessibilityLabel={_(msg`Username is available`)}\n                accessibilityHint=\"\"\n                style={a.z_20}>\n                <CheckIcon style={{color: t.palette.positive_500}} />\n              </View>\n            )}\n          </TextField.Root>\n        </View>\n        <LayoutAnimationConfig skipEntering skipExiting>\n          {/* Reserve space for one line of text to avoid layout shift. */}\n          <View style={[a.gap_xs, {minHeight: 21}]}>\n            {!!state.error && (\n              <Requirement>\n                <RequirementText>{state.error}</RequirementText>\n              </Requirement>\n            )}\n            {isHandleTaken && validCheck.overall && (\n              <>\n                <Requirement>\n                  <RequirementText>\n                    <Trans>\n                      {createFullHandle(draftValue, state.userDomain)} is not\n                      available\n                    </Trans>\n                  </RequirementText>\n                </Requirement>\n                {isHandleAvailable.suggestions &&\n                  isHandleAvailable.suggestions.length > 0 && (\n                    <HandleSuggestions\n                      sift={sift}\n                      suggestions={isHandleAvailable.suggestions}\n                      onSelect={suggestion => {\n                        setDraftValue(\n                          suggestion.handle.slice(\n                            0,\n                            state.userDomain.length * -1,\n                          ),\n                        )\n                        ax.metric('signup:handleSuggestionSelected', {\n                          method: suggestion.method,\n                        })\n                      }}\n                    />\n                  )}\n              </>\n            )}\n            {(!validCheck.handleChars || !validCheck.hyphenStartOrEnd) && (\n              <Requirement>\n                {!validCheck.hyphenStartOrEnd ? (\n                  <RequirementText>\n                    <Trans>Username cannot begin or end with a hyphen</Trans>\n                  </RequirementText>\n                ) : (\n                  <RequirementText>\n                    <Trans>\n                      Username must only contain letters (a-z), numbers, and\n                      hyphens\n                    </Trans>\n                  </RequirementText>\n                )}\n              </Requirement>\n            )}\n            <Requirement>\n              {(!validCheck.frontLengthNotTooLong ||\n                !validCheck.totalLength) && (\n                <RequirementText>\n                  <Trans>\n                    Username cannot be longer than{' '}\n                    <Plural\n                      value={MAX_SERVICE_HANDLE_LENGTH}\n                      other=\"# characters\"\n                    />\n                  </Trans>\n                </RequirementText>\n              )}\n            </Requirement>\n          </View>\n        </LayoutAnimationConfig>\n      </View>\n      <Animated.View layout={native(LinearTransition)}>\n        <BackNextButtons\n          isLoading={isNextLoading}\n          isNextDisabled={isNextDisabled}\n          onBackPress={onBackPress}\n          onNextPress={() => void onNextPress()}\n        />\n      </Animated.View>\n    </>\n  )\n}","file":"src/screens/Signup/StepHandle/index.tsx","kind":"component","line":36,"members":{"ax":[38,38],"draftValue":[41,41],"isNextLoading":[42,42],"onBackPress":[123,131],"onNextPress":[66,121],"sift":[49,49],"t":[39,39]},"supers":[]},"StepInfo":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-widgets","Screen \u00b7 component composition"],["sign-up","h-sequence","Create an account \u00b7 sequence"]],"code":"export function StepInfo({\n  onPressBack,\n  isServerError,\n  refetchServer,\n  isLoadingStarterPack,\n}: {\n  onPressBack: () => void\n  isServerError: boolean\n  refetchServer: () => void\n  isLoadingStarterPack: boolean\n}) {\n  const {t: l} = useLingui()\n  const ax = useAnalytics()\n  const {state, dispatch} = useSignupContext()\n  const preemptivelyCompleteActivePolicyUpdate =\n    usePreemptivelyCompleteActivePolicyUpdate()\n\n  /**\n   * The last email we ran the \"did you really mean this?\" check against, so\n   * the warning is only shown once per distinct address.\n   */\n  const prevEmailValueRef = useRef<string>(state.email)\n\n  const emailInputRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const passwordInputRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const birthdateInputRef = useRef<DateFieldRef>(null)\n\n  const aaRegionConfig = useAgeAssuranceRegionConfigWithFallback()\n  const {setDeviceGeolocation} = useDeviceGeolocationApi()\n  const locationControl = Dialog.useDialogControl()\n  const isOverRegionMinAccessAge = state.dateOfBirth\n    ? !isUnderAge(state.dateOfBirth.toISOString(), aaRegionConfig.minAccessAge)\n    : true\n  const isOverAppMinAccessAge = state.dateOfBirth\n    ? !isUnderAge(state.dateOfBirth.toISOString(), MIN_ACCESS_AGE)\n    : true\n  const isOverMinAdultAge = state.dateOfBirth\n    ? !isUnderAge(state.dateOfBirth.toISOString(), 18)\n    : true\n  const isDeviceGeolocationGranted = useIsDeviceGeolocationGranted()\n\n  const [hasWarnedEmail, setHasWarnedEmail] = useState<boolean>(false)\n\n  const tldtsRef = useRef<typeof tldts>(undefined)\n  useEffect(() => {\n    void loadTLDs().then(tldts => {\n      tldtsRef.current = tldts\n    })\n    // This will get used in the avatar creator a few steps later, so lets preload it now\n    void preloadViewShot()\n  }, [])\n\n  const onNextPress = () => {\n    const {inviteCode, email, password} = state\n    const emailChanged = prevEmailValueRef.current !== email\n\n    if (!isOverRegionMinAccessAge) {\n      return\n    }\n\n    if (state.serviceDescription?.inviteCodeRequired && !inviteCode) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please enter your invite code.`,\n        field: 'invite-code',\n      })\n    }\n    if (!email) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please enter your email.`,\n        field: 'email',\n      })\n    }\n    if (!EmailValidator.validate(email)) {\n      return dispatch({\n        type: 'setError',\n        value: l`Your email appears to be invalid.`,\n        field: 'email',\n      })\n    }\n    if (emailChanged && tldtsRef.current) {\n      if (isEmailMaybeInvalid(email, tldtsRef.current)) {\n        prevEmailValueRef.current = email\n        setHasWarnedEmail(true)\n        return dispatch({\n          type: 'setError',\n          value: l`Please double-check that you have entered your email address correctly.`,\n        })\n      }\n    } else if (hasWarnedEmail) {\n      setHasWarnedEmail(false)\n    }\n    prevEmailValueRef.current = email\n    if (!password) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please choose your password.`,\n        field: 'password',\n      })\n    }\n    if (password.length < 8) {\n      return dispatch({\n        type: 'setError',\n        value: l`Your password must be at least 8 characters long.`,\n        field: 'password',\n      })\n    }\n    if (!state.dateOfBirth) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please enter your date of birth.`,\n        field: 'date-of-birth',\n      })\n    }\n\n    preemptivelyCompleteActivePolicyUpdate()\n    dispatch({type: 'next'})\n    ax.metric('signup:nextPressed', {\n      activeStep: state.activeStep,\n    })\n  }\n\n  return (\n    <>\n      <View style={[a.gap_md, a.pt_lg]}>\n        {!!state.error && (\n          <Admonition.Admonition type=\"error\">\n            {state.error}\n          </Admonition.Admonition>\n        )}\n        <HostingProvider\n          minimal\n          serviceUrl={state.serviceUrl}\n          onSelectServiceUrl={v => dispatch({type: 'setServiceUrl', value: v})}\n        />\n        {state.isLoading || isLoadingStarterPack ? (\n          <View style={[a.align_center]}>\n            <Loader size=\"xl\" />\n          </View>\n        ) : state.serviceDescription ? (\n          <>\n            {state.serviceDescription.inviteCodeRequired && (\n              <View>\n                <TextField.LabelText>\n                  <Trans>Invite code</Trans>\n                </TextField.LabelText>\n                <TextField.Root isInvalid={state.errorField === 'invite-code'}>\n                  <TextField.Icon icon={Ticket} />\n                  <TextField.Input\n                    onChangeText={value => {\n                      dispatch({type: 'setInviteCode', value: value.trim()})\n                      if (\n                        state.errorField === 'invite-code' &&\n                        value.trim().length > 0\n                      ) {\n                        dispatch({type: 'clearError'})\n                      }\n                    }}\n                    label={l`Required for this provider`}\n                    value={state.inviteCode}\n                    autoCapitalize=\"none\"\n                    autoComplete=\"email\"\n                    keyboardType=\"email-address\"\n                    returnKeyType=\"next\"\n                    submitBehavior={native('submit')}\n                    onSubmitEditing={native(() =>\n                      emailInputRef.current?.focus(),\n                    )}\n                  />\n                </TextField.Root>\n              </View>\n            )}\n            <View>\n              <TextField.LabelText>\n                <Trans>Email</Trans>\n              </TextField.LabelText>\n              <TextField.Root isInvalid={state.errorField === 'email'}>\n                <TextField.Icon icon={Envelope} />\n                <TextField.Input\n                  testID=\"emailInput\"\n                  inputRef={emailInputRef}\n                  onChangeText={value => {\n                    dispatch({type: 'setEmail', value: value.trim()})\n                    if (hasWarnedEmail) {\n                      setHasWarnedEmail(false)\n                    }\n                    if (\n                      state.errorField === 'email' &&\n                      value.trim().length > 0 &&\n                      EmailValidator.validate(value.trim())\n                    ) {\n                      dispatch({type: 'clearError'})\n                    }\n                  }}\n                  label={l`Enter your email address`}\n                  value={state.email}\n                  autoCapitalize=\"none\"\n                  autoComplete=\"email\"\n                  keyboardType=\"email-address\"\n                  returnKeyType=\"next\"\n                  submitBehavior={native('submit')}\n                  onSubmitEditing={native(() =>\n                    passwordInputRef.current?.focus(),\n                  )}\n                />\n              </TextField.Root>\n            </View>\n            <View>\n              <TextField.LabelText>\n                <Trans>Password</Trans>\n              </TextField.LabelText>\n              <PasswordField\n                isInvalid={state.errorField === 'password'}\n                testID=\"passwordInput\"\n                inputRef={passwordInputRef}\n                onChangeText={value => {\n                  dispatch({type: 'setPassword', value})\n                  if (state.errorField === 'password' && value.length >= 8) {\n                    dispatch({type: 'clearError'})\n                  }\n                }}\n                label={l`Choose your password`}\n                value={state.password}\n                autoComplete=\"new-password\"\n                returnKeyType=\"next\"\n                submitBehavior={native('blurAndSubmit')}\n                onSubmitEditing={native(() =>\n                  birthdateInputRef.current?.focus(),\n                )}\n                passwordRules=\"minlength: 8;\"\n              />\n            </View>\n            <View>\n              <DateField.LabelText>\n                <Trans>Your birth date</Trans>\n              </DateField.LabelText>\n              <DateField.DateField\n                testID=\"date\"\n                inputRef={birthdateInputRef}\n                value={state.dateOfBirth ?? ''}\n                isInvalid={state.errorField === 'date-of-birth'}\n                onChangeDate={date => {\n                  dispatch({\n                    type: 'setDateOfBirth',\n                    value: sanitizeDate(new Date(date)),\n                  })\n                  if (state.errorField === 'date-of-birth') {\n                    dispatch({type: 'clearError'})\n                  }\n                }}\n                label={l`Date of birth`}\n                placeholder={l`Select your date of birth`}\n                accessibilityHint={l`Select your date of birth`}\n                maximumDate={new Date()}\n              />\n            </View>\n\n            <View style={[a.gap_sm]}>\n              <Policies serviceDescription={state.serviceDescription} />\n\n              {!isOverRegionMinAccessAge || !isOverAppMinAccessAge ? (\n                <Admonition.Outer type=\"error\">\n                  <Admonition.Row>\n                    <Admonition.Icon />\n                    <Admonition.Content>\n                      <Admonition.Text>\n                        <Plural\n                          value={aaRegionConfig.minAccessAge}\n                          other=\"You must be # years of age or older to create an account in your region.\"\n                        />\n                      </Admonition.Text>\n                      {IS_NATIVE &&\n                        !isDeviceGeolocationGranted &&\n                        isOverAppMinAccessAge && (\n                          <Admonition.Text>\n                            <Trans>\n                              Have we got your location wrong?{' '}\n                              <SimpleInlineLinkText\n                                label={l`Tap here to update your location with GPS.`}\n                                {...createStaticClick(() => {\n                                  locationControl.open()\n                                })}>\n                                Tap here to update your location with GPS.\n                              </SimpleInlineLinkText>\n                            </Trans>\n                          </Admonition.Text>\n                        )}\n                    </Admonition.Content>\n                  </Admonition.Row>\n                </Admonition.Outer>\n              ) : !isOverMinAdultAge ? (\n                <Admonition.Admonition type=\"warning\">\n                  <Trans>\n                    If you are not yet an adult according to the laws of your\n                    country, your parent or legal guardian must read these Terms\n                    on your behalf.\n                  </Trans>\n                </Admonition.Admonition>\n              ) : undefined}\n            </View>\n\n            {IS_NATIVE && (\n              <DeviceLocationRequestDialog\n                control={locationControl}\n                onLocationAcquired={props => {\n                  props.closeDialog(() => {\n                    // set this after close!\n                    setDeviceGeolocation(props.geolocation)\n                    Toast.show(l`Your location has been updated.`, {\n                      type: 'success',\n                    })\n                  })\n                }}\n              />\n            )}\n          </>\n        ) : undefined}\n      </View>\n      <BackNextButtons\n        hideNext={!isOverRegionMinAccessAge}\n        showRetry={isServerError}\n        isLoading={state.isLoading}\n        onBackPress={onPressBack}\n        onNextPress={onNextPress}\n        onRetryPress={refetchServer}\n        overrideNextText={hasWarnedEmail ? l`It's correct` : undefined}\n      />\n    </>\n  )\n}","file":"src/screens/Signup/StepInfo/index.tsx","kind":"component","line":62,"members":{"aaRegionConfig":[89,89],"ax":[74,74],"birthdateInputRef":[87,87],"emailInputRef":[85,85],"hasWarnedEmail":[103,103],"isDeviceGeolocationGranted":[101,101],"isLoadingStarterPack":[62,72],"isServerError":[62,72],"locationControl":[91,91],"onNextPress":[114,183],"onPressBack":[62,72],"passwordInputRef":[86,86],"preemptivelyCompleteActivePolicyUpdate":[76,77],"prevEmailValueRef":[83,83],"refetchServer":[62,72],"tldtsRef":[105,105]},"shot":"shots/code/StepInfo.jpg","supers":[]},"useHandleAvailabilityQuery":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"]],"code":"export function useHandleAvailabilityQuery(\n  {\n    username,\n    serviceDomain,\n    serviceDid,\n    enabled,\n    birthDate,\n    email,\n  }: {\n    username: string\n    serviceDomain: string\n    serviceDid: string\n    enabled: boolean\n    birthDate?: string\n    email?: string\n  },\n  debounceDelayMs = 500,\n) {\n  const ax = useAnalytics()\n  const name = username.trim()\n  const debouncedHandle = useDebouncedValue(name, debounceDelayMs)\n\n  return {\n    debouncedUsername: debouncedHandle,\n    enabled: enabled && name === debouncedHandle,\n    query: useQuery({\n      enabled: enabled && name === debouncedHandle,\n      queryKey: RQKEY_handleAvailability(\n        debouncedHandle,\n        serviceDomain,\n        serviceDid,\n      ),\n      queryFn: async () => {\n        const handle = createFullHandle(name, serviceDomain)\n        const res = await checkHandleAvailability(handle, serviceDid, {\n          email,\n          birthDate,\n        })\n        if (res.available) {\n          ax.metric('signup:handleAvailable', {typeahead: true})\n        } else {\n          ax.metric('signup:handleTaken', {typeahead: true})\n        }\n        return res\n      },\n    }),\n  }\n}","file":"src/state/queries/handle-availability.ts","kind":"hook","line":22,"members":{"ax":[40,40],"debouncedHandle":[42,42],"debouncedUsername":[45,45],"enabled":[46,46],"query":[47,67]},"supers":[]},"useSubmitSignup":{"appearsIn":[["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-sequence","Create an account \u00b7 sequence"]],"code":"export function useSubmitSignup() {\n  const ax = useAnalytics()\n  const {t: l} = useLingui()\n  const {createAccount} = useSessionApi()\n  const onboardingDispatch = useOnboardingDispatch()\n\n  return useCallback(\n    async (state: SignupState, dispatch: (action: SignupAction) => void) => {\n      if (!state.email) {\n        dispatch({type: 'setStep', value: SignupStep.INFO})\n        return dispatch({\n          type: 'setError',\n          value: l`Please enter your email.`,\n          field: 'email',\n        })\n      }\n      if (!EmailValidator.validate(state.email)) {\n        dispatch({type: 'setStep', value: SignupStep.INFO})\n        return dispatch({\n          type: 'setError',\n          value: l`Your email appears to be invalid.`,\n          field: 'email',\n        })\n      }\n      if (!state.password) {\n        dispatch({type: 'setStep', value: SignupStep.INFO})\n        return dispatch({\n          type: 'setError',\n          value: l`Please choose your password.`,\n          field: 'password',\n        })\n      }\n      if (!state.handle) {\n        dispatch({type: 'setStep', value: SignupStep.HANDLE})\n        return dispatch({\n          type: 'setError',\n          value: l`Please choose your handle.`,\n          field: 'handle',\n        })\n      }\n      const dateOfBirth = state.dateOfBirth\n      // This should never happen: StepInfo requires a birth date before advancing.\n      if (!dateOfBirth) {\n        dispatch({type: 'setStep', value: SignupStep.INFO})\n        return dispatch({\n          type: 'setError',\n          value: l`Please enter your date of birth.`,\n          field: 'date-of-birth',\n        })\n      }\n      if (\n        state.serviceDescription?.phoneVerificationRequired &&\n        !state.pendingSubmit?.verificationCode\n      ) {\n        dispatch({type: 'setStep', value: SignupStep.CAPTCHA})\n        ax.logger.error('Signup: captcha code missing at submit', {})\n        return dispatch({\n          type: 'setError',\n          value: l`Please complete the verification captcha.`,\n        })\n      }\n      dispatch({type: 'setError', value: ''})\n      dispatch({type: 'setIsLoading', value: true})\n\n      const verificationCode = state.pendingSubmit?.verificationCode\n      try {\n        await createAccount(\n          {\n            service: state.serviceUrl,\n            email: state.email,\n            handle: createFullHandle(state.handle, state.userDomain),\n            password: state.password,\n            birthDate: dateOfBirth,\n            inviteCode: state.inviteCode.trim(),\n            verificationCode,\n          },\n          {\n            signupDuration: Date.now() - state.signupStartTime,\n            fieldErrorsTotal: Object.values(state.fieldErrors).reduce(\n              (a, b) => a + b,\n              0,\n            ),\n            backgroundCount: state.backgroundCount,\n          },\n        )\n\n        /*\n         * Must happen last so that if the user has multiple tabs open and\n         * createAccount fails, one tab is not stuck in onboarding \u2014\u00a0Eric\n         */\n        onboardingDispatch({type: 'start'})\n      } catch (err) {\n        const e = err as Error\n        if (\n          matchXrpcError(e, com.atproto.server.createAccount) ===\n          'InvalidInviteCode'\n        ) {\n          dispatch({\n            type: 'setError',\n            value: l`Invite code not accepted. Check that you input it correctly and try again.`,\n            field: 'invite-code',\n          })\n          dispatch({type: 'setStep', value: SignupStep.INFO})\n          dispatch({type: 'setIsLoading', value: false})\n          return\n        }\n\n        /* the error object, not its stringification: cleanError only extracts\n         * the clean server message from a live LexError */\n        const error = cleanError(e)\n        const isHandleError = error.toLowerCase().includes('handle')\n\n        dispatch({type: 'setIsLoading', value: false})\n        dispatch({\n          type: 'setError',\n          value: error,\n          field: isHandleError ? 'handle' : undefined,\n        })\n        dispatch({\n          type: 'setStep',\n          value: isHandleError ? SignupStep.HANDLE : SignupStep.INFO,\n        })\n\n        const expected = classifyExpectedSignupError(e)\n        if (expected) {\n          ax.metric('signup:createAccountFailure', {reason: expected})\n        } else {\n          ax.logger.error('Signup: unexpected createAccount failure', {\n            safeMessage: e,\n          })\n        }\n      }\n      dispatch({type: 'setIsLoading', value: false})\n    },\n    [l, ax, createAccount, onboardingDispatch],\n  )\n}","file":"src/screens/Signup/state.ts","kind":"hook","line":267,"members":{"ax":[268,268],"onboardingDispatch":[271,271]},"supers":[]}},"sourceUrl":"https://github.com/bluesky-social/social-app/blob/f7399a645c08dcf5d15f8cac64417ac73fe6ddf9/"};
